#include <memory>
#include <iostream>

class Widget {};

int main() {
    // A shared_ptr is typically twice the size of a raw pointer.
    std::cout << "Size of raw pointer: " << sizeof(Widget*) << " bytes\n";
    std::cout << "Size of shared_ptr: " << sizeof(std::shared_ptr<Widget>) << " bytes\n";
    std::cout << "Size of unique_ptr: " << sizeof(std::unique_ptr<Widget>) << " bytes\n";

    // Scenario 1: Two allocations (object + control block)
    // This is less efficient and not exception-safe in complex expressions.
    std::shared_ptr<Widget> sp1(new Widget());

    // Scenario 2: One allocation (object + control block together)
    // This is the preferred method for performance and safety.
    auto sp2 = std::make_shared<Widget>();

    // Operations involving reference counting have a small atomic overhead.
    auto sp3 = sp2; // Atomic increment of the reference count.
    sp2.reset();    // Atomic decrement.
    // When sp3 goes out of scope, another atomic decrement occurs.
}
